const SEND_BUTTONS_ALLOWED_COMPLEX = new Set(['cta_url', 'cta_copy', 'cta_call']);
const INTERACTIVE_ALLOWED_NAMES = new Set([
  'quick_reply', 'cta_url', 'cta_copy', 'cta_call', 'cta_catalog', 'cta_reminder', 'cta_cancel_reminder',
  'address_message', 'send_location', 'open_webview', 'mpm', 'wa_payment_transaction_details',
  'automated_greeting_message_view_catalog', 'galaxy_message', 'single_select', 'innap', 'inapp_signup'
]);

// Alias untuk nama button yang merujuk ke implementasi yang sama.
// 'innap' dipetakan ke 'inapp_signup', native flow name asli WhatsApp untuk in-app signup.
const NAME_ALIASES = {
  innap: 'inapp_signup'
};

function resolveButtonName(name) {
  return NAME_ALIASES[name] || name;
}

const REQUIRED_FIELDS_MAP = {
  cta_url: ['display_text', 'url'],
  cta_copy: ['display_text', 'copy_code'],
  cta_call: ['display_text', 'phone_number'],
  cta_catalog: ['business_phone_number'],
  cta_reminder: ['display_text'],
  cta_cancel_reminder: ['display_text'],
  address_message: ['display_text'],
  send_location: ['display_text'],
  open_webview: ['title', 'link'],
  innap: [],
  inapp_signup: [],
  mpm: ['product_id'],
  wa_payment_transaction_details: ['transaction_id'],
  automated_greeting_message_view_catalog: ['business_phone_number', 'catalog_product_id'],
  galaxy_message: ['flow_token', 'flow_id'],
  single_select: ['title', 'sections'],
  quick_reply: ['display_text', 'id']
};

function parseButtonParams(name, buttonParamsJson, errors, warnings, index) {
  let parsed;
  try {
    parsed = JSON.parse(buttonParamsJson);
  } catch (e) {
    errors.push(`button[${index}] (${name}) JSON tidak valid: ${e.message}`);
    return null;
  }

  const req = REQUIRED_FIELDS_MAP[name] || [];
  for (const f of req) {
    if (!(f in parsed)) {
      errors.push(`button[${index}] (${name}) field wajib '${f}' tidak ditemukan`);
    }
  }

  if (name === 'open_webview' && parsed.link) {
    if (typeof parsed.link !== 'object' || !parsed.link.url) {
      errors.push(`button[${index}] (open_webview) link.url diperlukan`);
    }
  }

  if (name === 'single_select') {
    if (!Array.isArray(parsed.sections) || parsed.sections.length === 0) {
      errors.push(`button[${index}] (single_select) sections harus berupa array tidak kosong`);
    }
  }

  return parsed;
}

function buildInteractiveButtons(buttons = []) {
  return buttons.map((b, i) => {
    if (b && b.name && b.buttonParamsJson) return b;

    if (b && (b.id || b.text)) {
      return {
        name: 'quick_reply',
        buttonParamsJson: JSON.stringify({
          display_text: b.text || b.displayText || 'Tombol ' + (i + 1),
          id: b.id || ('quick_' + (i + 1))
        })
      };
    }

    if (b && b.buttonId && b.buttonText?.displayText) {
      return {
        name: 'quick_reply',
        buttonParamsJson: JSON.stringify({
          display_text: b.buttonText.displayText,
          id: b.buttonId
        })
      };
    }

    return b;
  });
}

function validateAuthoringButtons(buttons) {
  const errors = [];
  const warnings = [];

  if (buttons == null) {
    return { errors: [], warnings: [], valid: true, cleaned: [] };
  }

  if (!Array.isArray(buttons)) {
    errors.push('buttons harus berupa array');
    return { errors, warnings, valid: false, cleaned: [] };
  }

  const SOFT_BUTTON_CAP = 25;
  if (buttons.length === 0) {
    warnings.push('array buttons kosong');
  } else if (buttons.length > SOFT_BUTTON_CAP) {
    warnings.push(`jumlah buttons (${buttons.length}) melebihi batas ${SOFT_BUTTON_CAP}; mungkin akan ditolak oleh klien`);
  }

  const cleaned = buttons.map((b, idx) => {
    if (b == null || typeof b !== 'object') {
      errors.push(`button[${idx}] bukan objek`);
      return b;
    }

    if (b.name && b.buttonParamsJson) {
      if (typeof b.buttonParamsJson !== 'string') {
        errors.push(`button[${idx}] buttonParamsJson harus berupa string`);
      } else {
        try {
          JSON.parse(b.buttonParamsJson);
        } catch (e) {
          errors.push(`button[${idx}] buttonParamsJson bukan JSON valid: ${e.message}`);
        }
      }
      return b;
    }

    if (b.id || b.text || b.displayText) {
      if (!(b.id || b.text || b.displayText)) {
        errors.push(`button[${idx}] bentuk legacy tidak memiliki id atau text/displayText`);
      }
      return b;
    }

    if (b.buttonId && b.buttonText && typeof b.buttonText === 'object' && b.buttonText.displayText) {
      return b;
    }

    if (b.buttonParamsJson) {
      if (typeof b.buttonParamsJson !== 'string') {
        warnings.push(`button[${idx}] memiliki buttonParamsJson non-string; akan mencoba stringify`);
        try {
          b.buttonParamsJson = JSON.stringify(b.buttonParamsJson);
        } catch {
          errors.push(`button[${idx}] buttonParamsJson tidak dapat diserialisasi`);
        }
      } else {
        try { JSON.parse(b.buttonParamsJson); } catch (e) { warnings.push(`button[${idx}] buttonParamsJson bukan JSON valid (${e.message})`); }
      }
      if (!b.name) {
        warnings.push(`button[${idx}] tidak memiliki nama; menggunakan default quick_reply`);
        b.name = 'quick_reply';
      }
      return b;
    }

    warnings.push(`button[${idx}] bentuk tidak dikenali; diteruskan tanpa perubahan`);
    return b;
  });

  return { errors, warnings, valid: errors.length === 0, cleaned };
}

function validateSendButtonsPayload(data) {
  const errors = [];
  const warnings = [];

  if (!data || typeof data !== 'object') {
    return { valid: false, errors: ['payload harus berupa objek'], warnings };
  }

  if (!data.text || typeof data.text !== 'string') {
    errors.push('text wajib dan harus berupa string');
  }

  if (!Array.isArray(data.buttons) || data.buttons.length === 0) {
    errors.push('buttons wajib dan harus berupa array tidak kosong');
  } else {
    data.buttons.forEach((btn, i) => {
      if (!btn || typeof btn !== 'object') {
        errors.push(`button[${i}] harus berupa objek`);
        return;
      }

      if (btn.id && btn.text) {
        if (typeof btn.id !== 'string' || typeof btn.text !== 'string') {
          errors.push(`button[${i}] id/text legacy quick reply harus berupa string`);
        }
        return;
      }

      if (btn.name && btn.buttonParamsJson) {
        if (!SEND_BUTTONS_ALLOWED_COMPLEX.has(btn.name)) {
          errors.push(`button[${i}] nama '${btn.name}' tidak diizinkan dalam sendButtons`);
          return;
        }

        if (typeof btn.buttonParamsJson !== 'string') {
          errors.push(`button[${i}] buttonParamsJson harus berupa string`);
          return;
        }

        parseButtonParams(btn.name, btn.buttonParamsJson, errors, warnings, i);
        return;
      }

      errors.push(`button[${i}] bentuk tidak valid (harus legacy quick reply atau bernama ${Array.from(SEND_BUTTONS_ALLOWED_COMPLEX).join(', ')})`);
    });
  }

  return { valid: errors.length === 0, errors, warnings };
}

function validateSendInteractiveMessagePayload(data) {
  const errors = [];
  const warnings = [];

  if (!data || typeof data !== 'object') {
    return { valid: false, errors: ['payload harus berupa objek'], warnings };
  }

  if (!data.text || typeof data.text !== 'string') {
    errors.push('text wajib dan harus berupa string');
  }

  if (!Array.isArray(data.interactiveButtons) || data.interactiveButtons.length === 0) {
    errors.push('interactiveButtons wajib dan harus berupa array tidak kosong');
  } else {
    data.interactiveButtons.forEach((btn, i) => {
      if (!btn || typeof btn !== 'object') {
        errors.push(`interactiveButtons[${i}] harus berupa objek`);
        return;
      }

      if (!btn.name || typeof btn.name !== 'string') {
        errors.push(`interactiveButtons[${i}] nama tidak ditemukan`);
        return;
      }

      if (!INTERACTIVE_ALLOWED_NAMES.has(btn.name)) {
        errors.push(`interactiveButtons[${i}] nama '${btn.name}' tidak diizinkan`);
        return;
      }

      if (!btn.buttonParamsJson || typeof btn.buttonParamsJson !== 'string') {
        errors.push(`interactiveButtons[${i}] buttonParamsJson harus berupa string`);
        return;
      }

      parseButtonParams(btn.name, btn.buttonParamsJson, errors, warnings, i);
    });
  }

  return { valid: errors.length === 0, errors, warnings };
}

function validateInteractiveMessageContent(content) {
  const errors = [];
  const warnings = [];

  if (!content || typeof content !== 'object') {
    return { errors: ['content harus berupa objek'], warnings, valid: false };
  }

  const interactive = content.interactiveMessage;
  if (!interactive) {
    return { errors, warnings, valid: true };
  }

  const nativeFlow = interactive.nativeFlowMessage;
  if (!nativeFlow) {
    errors.push('interactiveMessage.nativeFlowMessage tidak ditemukan');
    return { errors, warnings, valid: false };
  }

  if (!Array.isArray(nativeFlow.buttons)) {
    errors.push('nativeFlowMessage.buttons harus berupa array');
    return { errors, warnings, valid: false };
  }

  if (nativeFlow.buttons.length === 0) {
    warnings.push('nativeFlowMessage.buttons kosong');
  }

  nativeFlow.buttons.forEach((btn, i) => {
    if (!btn || typeof btn !== 'object') {
      errors.push(`buttons[${i}] bukan objek`);
      return;
    }

    if (!btn.buttonParamsJson) {
      warnings.push(`buttons[${i}] buttonParamsJson tidak ditemukan (mungkin gagal dirender)`);
    } else if (typeof btn.buttonParamsJson !== 'string') {
      errors.push(`buttons[${i}] buttonParamsJson harus berupa string`);
    } else {
      try { JSON.parse(btn.buttonParamsJson); } catch (e) { warnings.push(`buttons[${i}] buttonParamsJson JSON tidak valid (${e.message})`); }
    }

    if (!btn.name) {
      warnings.push(`buttons[${i}] nama tidak ditemukan; menggunakan default quick_reply`);
      btn.name = 'quick_reply';
    }
  });

  return { errors, warnings, valid: errors.length === 0 };
}

function getButtonType(message) {
  if (message.listMessage) {
    return 'list';
  } else if (message.buttonsMessage) {
    return 'buttons';
  } else if (message.interactiveMessage?.nativeFlowMessage || message.interactiveMessage?.carouselMessage) {
    return 'native_flow';
  }
  return null;
}

function getButtonArgs(message) {
  const nativeFlow = message.interactiveMessage?.nativeFlowMessage;
  const carousel = message.interactiveMessage?.carouselMessage;
  const firstButtonName = nativeFlow?.buttons?.[0]?.name || carousel?.cards?.[0]?.nativeFlowMessage?.buttons?.[0]?.name;

  const nativeFlowSpecials = [
    'mpm', 'cta_catalog', 'send_location',
    'call_permission_request', 'wa_payment_transaction_details',
    'automated_greeting_message_view_catalog'
  ];

  if (carousel && !nativeFlow) {
    // Node biner untuk carouselMessage: dibungkus sebagai native_flow bernama 'carousel'.
    return {
      tag: 'biz',
      attrs: {},
      content: [{
        tag: 'interactive',
        attrs: {
          type: 'native_flow',
          v: '1'
        },
        content: [{
          tag: 'native_flow',
          attrs: {
            v: '1',
            name: 'carousel'
          }
        }]
      }]
    };
  } else if (nativeFlow && (firstButtonName === 'review_and_pay' || firstButtonName === 'payment_info')) {
    return {
      tag: 'biz',
      attrs: {
        native_flow_name: firstButtonName === 'review_and_pay' ? 'order_details' : firstButtonName
      }
    };
  } else if (nativeFlow && nativeFlowSpecials.includes(firstButtonName)) {
    return {
      tag: 'biz',
      attrs: {},
      content: [{
        tag: 'interactive',
        attrs: {
          type: 'native_flow',
          v: '1'
        },
        content: [{
          tag: 'native_flow',
          attrs: {
            v: '2',
            name: firstButtonName
          }
        }]
      }]
    };
  } else if (nativeFlow || message.buttonsMessage) {
    return {
      tag: 'biz',
      attrs: {},
      content: [{
        tag: 'interactive',
        attrs: {
          type: 'native_flow',
          v: '1'
        },
        content: [{
          tag: 'native_flow',
          attrs: {
            v: '9',
            name: 'mixed'
          }
        }]
      }]
    };
  } else if (message.listMessage) {
    return {
      tag: 'biz',
      attrs: {},
      content: [{
        tag: 'list',
        attrs: {
          v: '2',
          type: 'product_list'
        }
      }]
    };
  } else {
    return {
      tag: 'biz',
      attrs: {}
    };
  }
}

// Constrói header interactiveMessage. Sem foto/vídeo/documento -> hanya title (jika ada).
// Dengan foto/vídeo/dokumen -> upload media lewat prepareWAMessageMedia lalu set hasMediaAttachment.
async function buildMediaHeader(himmel, utils, source = {}) {
  const { image, video, document, title, subtitle } = source;
  const mediaKey = image ? 'image' : video ? 'video' : document ? 'document' : null;

  if (!mediaKey) {
    if (title || subtitle) {
      return { title: title || subtitle || '' };
    }
    return undefined;
  }

  if (typeof utils.prepareWAMessageMedia !== 'function') {
    throw new InteractiveValidationError('prepareWAMessageMedia tidak tersedia di paket baileys yang terinstal', {
      context: 'buildMediaHeader',
      errors: ['Header dengan foto/vídeo/dokumen membutuhkan prepareWAMessageMedia dari baileys / @whiskeysockets/baileys']
    });
  }

  const prepared = await utils.prepareWAMessageMedia(
  { [mediaKey]: source[mediaKey] },
  {
    upload: himmel.waUploadToServer,
    logger: himmel.logger,
    mediaCache: himmel.mediaCache
  }
);

if (mediaKey === "video" && source[mediaKey]?.gifPlayback) {
  if (prepared.videoMessage) {
    prepared.videoMessage.gifPlayback = true;
  }
}

const header = { ...prepared, hasMediaAttachment: true };
if (title || subtitle) header.title = title || subtitle;
return header;
}

function mapNativeFlowButtons(buttons = []) {
  return buttons.map(btn => ({
    name: resolveButtonName(btn.name || 'quick_reply'),
    buttonParamsJson: btn.buttonParamsJson
  }));
}

async function convertToInteractiveMessage(content, himmel, utils) {
  const hasButtons = Array.isArray(content.interactiveButtons) && content.interactiveButtons.length > 0;
  const hasCarousel = Array.isArray(content.carousel) && content.carousel.length > 0;

  if (!hasButtons && !hasCarousel) {
    return content;
  }

  const interactiveMessage = {};

  const hasHeaderMedia = Boolean(content.image || content.video || content.document);
  if (hasHeaderMedia || content.title || content.subtitle) {
    interactiveMessage.header = await buildMediaHeader(himmel, utils, content);
  }

  if (content.text) {
    interactiveMessage.body = { text: content.text };
  }

  if (content.footer) {
    interactiveMessage.footer = { text: content.footer };
  }

  // Carrossel: cada card memiliki header (opsional dengan foto/vídeo), body, dan tombolnya sendiri.
  if (hasCarousel) {
    interactiveMessage.carouselMessage = {
      cards: await Promise.all(content.carousel.map(async (card = {}) => {
        const cardMessage = {};

        const cardHeader = await buildMediaHeader(himmel, utils, card);
        if (cardHeader) cardMessage.header = cardHeader;

        if (card.text || card.caption) {
          cardMessage.body = { text: card.text || card.caption };
        }

        if (card.footer) {
          cardMessage.footer = { text: card.footer };
        }

        cardMessage.nativeFlowMessage = {
          buttons: mapNativeFlowButtons(buildInteractiveButtons(card.buttons || []))
        };

        return cardMessage;
      }))
    };
  }

  if (hasButtons) {
    interactiveMessage.nativeFlowMessage = {
      buttons: mapNativeFlowButtons(content.interactiveButtons)
    };
    if (content.messageParamsJson) {
      interactiveMessage.nativeFlowMessage.messageParamsJson = content.messageParamsJson;
    }
  }

  const newContent = { ...content };
  delete newContent.interactiveButtons;
  delete newContent.carousel;
  delete newContent.title;
  delete newContent.subtitle;
  delete newContent.text;
  delete newContent.footer;
  delete newContent.image;
  delete newContent.video;
  delete newContent.document;
  delete newContent.messageParamsJson;

  return { ...newContent, interactiveMessage };
}

const BAILEYS_CANDIDATE_PKGS = ['baileys', '@whiskeysockets/baileys', '@adiwajshing/baileys'];

// Import dinamis dan cache util internal baileys yang dibutuhkan di seluruh module ini
// (sendInteractiveMessage, sendAlbumMessage, header foto, carousel, dsb).
let _cachedUtils = null;
async function loadBaileysUtils(himmel, { context = 'loadBaileysUtils' } = {}) {
  if (_cachedUtils) {
    return { ..._cachedUtils, relayMessage: himmel.relayMessage };
  }

  let generateWAMessageFromContent, normalizeMessageContent, isJidGroup, generateMessageIDV2, prepareWAMessageMedia, proto;
  let loaded = false;

  for (const pkg of BAILEYS_CANDIDATE_PKGS) {
    if (loaded) break;
    try {
      const mod = await import(pkg);
      generateWAMessageFromContent = mod.generateWAMessageFromContent || mod.Utils?.generateWAMessageFromContent;
      normalizeMessageContent = mod.normalizeMessageContent || mod.Utils?.normalizeMessageContent;
      isJidGroup = mod.isJidGroup || mod.WABinary?.isJidGroup;
      generateMessageIDV2 = mod.generateMessageIDV2 || mod.Utils?.generateMessageIDV2 || mod.generateMessageID || mod.Utils?.generateMessageID;
      prepareWAMessageMedia = mod.prepareWAMessageMedia || mod.Utils?.prepareWAMessageMedia;
      proto = mod.proto || mod.WAProto?.proto || mod.WAProto;

      if (generateWAMessageFromContent && normalizeMessageContent && isJidGroup) {
        loaded = true;
      }
    } catch (_) { }
  }

  if (!loaded) {
    throw new InteractiveValidationError('Internal baileys tidak ditemukan', {
      context,
      errors: ['generateWAMessageFromContent atau normalizeMessageContent tidak ditemukan dalam paket yang terinstal: baileys / @whiskeysockets/baileys / @adiwajshing/baileys'],
      example: { install: 'npm i baileys', requireUsage: "import { generateWAMessageFromContent } from 'baileys'" }
    });
  }

  _cachedUtils = { generateWAMessageFromContent, normalizeMessageContent, isJidGroup, generateMessageIDV2, prepareWAMessageMedia, proto };
  return { ..._cachedUtils, relayMessage: himmel.relayMessage };
}

async function sendInteractiveMessage(himmel, jid, content, options = {}) {
  if (!himmel) {
    throw new InteractiveValidationError('Socket diperlukan', { context: 'sendInteractiveMessage' });
  }

  if (content && Array.isArray(content.interactiveButtons)) {
    const strict = validateSendInteractiveMessagePayload(content);
    if (!strict.valid) {
      throw new InteractiveValidationError('Payload authoring interaktif tidak valid', {
        context: 'sendInteractiveMessage.validateSendInteractiveMessagePayload',
        errors: strict.errors,
        warnings: strict.warnings,
        example: EXAMPLE_PAYLOADS.sendInteractiveMessage
      });
    }
  }

  const {
    generateWAMessageFromContent,
    relayMessage,
    normalizeMessageContent,
    isJidGroup,
    generateMessageIDV2,
    prepareWAMessageMedia
  } = await loadBaileysUtils(himmel, { context: 'sendInteractiveMessage.dynamicImport' });

  const convertedContent = await convertToInteractiveMessage(content, himmel, { prepareWAMessageMedia });

  const { errors: contentErrors, warnings: contentWarnings, valid: contentValid } = validateInteractiveMessageContent(convertedContent);
  if (!contentValid) {
    throw new InteractiveValidationError('Konten interaktif yang dikonversi tidak valid', {
      context: 'sendInteractiveMessage.validateInteractiveMessageContent',
      errors: contentErrors,
      warnings: contentWarnings,
      example: await convertToInteractiveMessage(EXAMPLE_PAYLOADS.sendInteractiveMessage, himmel, { prepareWAMessageMedia })
    });
  }

  if (!relayMessage) {
    throw new InteractiveValidationError('Socket tidak memiliki relayMessage', { context: 'sendInteractiveMessage' });
  }

  const userJid = himmel.authState?.creds?.me?.id || himmel.user?.id;
  const fullMsg = generateWAMessageFromContent(jid, convertedContent, {
    logger: himmel.logger,
    userJid,
    messageId: generateMessageIDV2(userJid),
    timestamp: new Date(),
    ...options
  });

  const normalizedContent = normalizeMessageContent(fullMsg.message);
  const buttonType = getButtonType(normalizedContent);
  let additionalNodes = [...(options.additionalNodes || [])];

  if (buttonType) {
    const buttonsNode = getButtonArgs(normalizedContent);
    const isPrivate = !isJidGroup(jid);
    additionalNodes.push(buttonsNode);

    if (isPrivate) {
      additionalNodes.push({ tag: 'bot', attrs: { biz_bot: '1' } });
    }
  }

  await relayMessage(jid, fullMsg.message, {
    messageId: fullMsg.key.id,
    useCachedGroupMetadata: options.useCachedGroupMetadata,
    additionalAttributes: options.additionalAttributes || {},
    statusJidList: options.statusJidList,
    additionalNodes
  });

  const isPrivateChat = !isJidGroup(jid);
  if (himmel.config?.emitOwnEvents && isPrivateChat) {
    process.nextTick(() => {
      if (himmel.processingMutex?.mutex && himmel.upsertMessage) {
        himmel.processingMutex.mutex(() => himmel.upsertMessage(fullMsg, 'append'));
      }
    });
  }

  return fullMsg;
}

async function sendInteractiveButtonsBasic(himmel, jid, data = {}, options = {}) {
  if (!himmel) {
    throw new InteractiveValidationError('Socket diperlukan', { context: 'sendButtons' });
  }

  const { text = '', footer = '', title, subtitle, buttons = [], image, video, document, carousel } = data;
  const strict = validateSendButtonsPayload({ text, buttons, title, subtitle, footer });

  if (!strict.valid) {
    throw new InteractiveValidationError('Payload tombol tidak valid', {
      context: 'sendButtons.validateSendButtonsPayload',
      errors: strict.errors,
      warnings: strict.warnings,
      example: EXAMPLE_PAYLOADS.sendButtons
    });
  }

  const { errors, warnings, cleaned } = validateAuthoringButtons(buttons);
  if (errors.length) {
    throw new InteractiveValidationError('Objek tombol authoring tidak valid', {
      context: 'sendButtons.validateAuthoringButtons',
      errors,
      warnings,
      example: EXAMPLE_PAYLOADS.sendButtons.buttons
    });
  }

  const interactiveButtons = buildInteractiveButtons(cleaned);
  const payload = { text, footer, interactiveButtons };

  if (title) payload.title = title;
  if (subtitle) payload.subtitle = subtitle;
  // Foto (dengan header media) vs Sem Foto (tanpa header media) - cukup isi salah satu.
  if (image) payload.image = image;
  if (video) payload.video = video;
  if (document) payload.document = document;
  // Carrossel: array of { image?, video?, title?, text?, footer?, buttons: [...] }
  if (Array.isArray(carousel) && carousel.length) payload.carousel = carousel;

  return sendInteractiveMessage(himmel, jid, payload, options);
}

// Mengirim beberapa foto/vídeo sebagai satu AlbumMessage (album WhatsApp).
// media: [{ type: 'image' | 'video', image?, video?, caption? }, ...]
async function sendAlbumMessage(himmel, jid, media = [], options = {}) {
  if (!himmel) {
    throw new InteractiveValidationError('Socket diperlukan', { context: 'sendAlbumMessage' });
  }

  if (!Array.isArray(media) || media.length === 0) {
    throw new InteractiveValidationError('media wajib berupa array tidak kosong', {
      context: 'sendAlbumMessage',
      example: EXAMPLE_PAYLOADS.sendAlbumMessage
    });
  }

  const errors = [];
  media.forEach((item, i) => {
    if (!item || typeof item !== 'object') {
      errors.push(`media[${i}] harus berupa objek`);
      return;
    }
    const type = item.type || (item.image ? 'image' : item.video ? 'video' : null);
    if (type !== 'image' && type !== 'video') {
      errors.push(`media[${i}] wajib memiliki type 'image' atau 'video' (atau field image/video)`);
      return;
    }
    if (!item[type]) {
      errors.push(`media[${i}] tidak memiliki konten '${type}'`);
    }
  });

  if (errors.length) {
    throw new InteractiveValidationError('Payload album tidak valid', {
      context: 'sendAlbumMessage.validate',
      errors,
      example: EXAMPLE_PAYLOADS.sendAlbumMessage
    });
  }

  const {
    generateWAMessageFromContent,
    relayMessage,
    isJidGroup,
    generateMessageIDV2,
    prepareWAMessageMedia
  } = await loadBaileysUtils(himmel, { context: 'sendAlbumMessage.dynamicImport' });

  if (!relayMessage) {
    throw new InteractiveValidationError('Socket tidak memiliki relayMessage', { context: 'sendAlbumMessage' });
  }
  if (typeof prepareWAMessageMedia !== 'function') {
    throw new InteractiveValidationError('prepareWAMessageMedia tidak tersedia di paket baileys yang terinstal', {
      context: 'sendAlbumMessage'
    });
  }

  const normalized = media.map(item => ({
    type: item.type || (item.image ? 'image' : 'video'),
    value: item.image || item.video,
    caption: item.caption || item.text
  }));

  const expectedImageCount = normalized.filter(m => m.type === 'image').length;
  const expectedVideoCount = normalized.filter(m => m.type === 'video').length;

  const userJid = himmel.authState?.creds?.me?.id || himmel.user?.id;

  const albumMsg = generateWAMessageFromContent(jid, {
    albumMessage: { expectedImageCount, expectedVideoCount }
  }, {
    logger: himmel.logger,
    userJid,
    messageId: generateMessageIDV2(userJid),
    timestamp: new Date(),
    ...options
  });

  await relayMessage(jid, albumMsg.message, {
    messageId: albumMsg.key.id,
    useCachedGroupMetadata: options.useCachedGroupMetadata,
    additionalAttributes: options.additionalAttributes || {},
    statusJidList: options.statusJidList
  });

  const sentMedia = [];
  for (const item of normalized) {
    const prepared = await prepareWAMessageMedia(
      { [item.type]: item.value },
      { upload: himmel.waUploadToServer, logger: himmel.logger, mediaCache: himmel.mediaCache }
    );

    const mediaKey = item.type === 'image' ? 'imageMessage' : 'videoMessage';
    if (item.caption && prepared[mediaKey]) {
      prepared[mediaKey].caption = item.caption;
    }
    // Menautkan foto/vídeo ke album induk sesuai skema albumMessage WhatsApp.
    if (prepared[mediaKey]) {
      prepared[mediaKey].contextInfo = {
        ...(prepared[mediaKey].contextInfo || {}),
        messageAssociation: {
          associationType: 1, // 1 = MEDIA_ALBUM
          parentMessageKey: albumMsg.key
        }
      };
    }

    const mediaMsg = generateWAMessageFromContent(jid, prepared, {
      logger: himmel.logger,
      userJid,
      messageId: generateMessageIDV2(userJid),
      timestamp: new Date()
    });

    await relayMessage(jid, mediaMsg.message, {
      messageId: mediaMsg.key.id,
      useCachedGroupMetadata: options.useCachedGroupMetadata,
      additionalAttributes: options.additionalAttributes || {}
    });

    sentMedia.push(mediaMsg);

    if (options.delay) {
      await new Promise(resolve => setTimeout(resolve, options.delay));
    }
  }

  const isPrivateChat = !isJidGroup(jid);
  if (himmel.config?.emitOwnEvents && isPrivateChat) {
    process.nextTick(() => {
      if (himmel.processingMutex?.mutex && himmel.upsertMessage) {
        himmel.processingMutex.mutex(() => himmel.upsertMessage(albumMsg, 'append'));
      }
    });
  }

  return { albumMessage: albumMsg, media: sentMedia };
}

export {
  sendInteractiveButtonsBasic as sendButtons,
  sendInteractiveMessage,
  sendAlbumMessage,
  getButtonType,
  getButtonArgs,
  InteractiveValidationError,
  validateAuthoringButtons,
  validateInteractiveMessageContent,
  validateSendButtonsPayload,
  validateSendInteractiveMessagePayload
};
